#include "resident/kernel/catalog_section_observation.hpp"
// 新目录只为原拜帖指定原本人接待节点，不能通过回信声明扩出组织代理、秘密或预约权。
#include "visit_reply.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
const VisitMessagePolicy* original(const VisitMessageCatalog& c,const StableId& id){for(const auto& p:c.policies)if(p.id==id)return &p;return nullptr;}
// 原接待节点必须仍为同一本人say；目录重复身份或自动命令节点均不能代本人确认。
Status declaration(const InteractionCatalog& c,const VisitMessagePolicy& p,const StableId& id){const DialogueDefinition* d=nullptr;for(const auto& row:c.dialogues)if(row.id==p.dialogue_id){if(d)return common_failure("VisitReplyDialogueRequired",id);d=&row;}if(!d||d->context_role!=p.role_id)return common_failure("VisitReplyDialogueRequired",id);const DialogueNode* node=nullptr;for(const auto& row:d->nodes)if(row.id==id){if(node)return common_failure("VisitReplyDeclarationRequired",id);node=&row;}if(!node||node->kind!="say"||(node->speaker!="$provider"&&node->speaker!=p.custodian_actor_id)||node->command)return common_failure("VisitReplyDeclarationRequired",id);return common_success();}
}
Status validate_visit_reply_catalog(const VisitReplyCatalog& c,const VisitMessageCatalog& messages,const InteractionCatalog& interactions){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 63, "VisitReplyCatalog", "validate_visit_reply_catalog", &c);
auto valid=validate_visit_message_catalog(messages,interactions);if(!valid.ok)return valid;if(!visit_reply_version(c.version)||c.policies.empty()||c.policies.size()>4096)return common_failure("InvalidVisitReplyCatalog");if((visit_reply_life_version(c.version)?(messages.version<2||messages.version>3):messages.version!=1))return common_failure("VisitReplyOriginalProfileRequired");std::set<StableId> ids,originals;for(const auto& p:c.policies){if(p.id.empty()||p.id.size()>256||!ids.insert(p.id).second||!originals.insert(p.message_policy_id).second)return common_failure("InvalidVisitReplyPolicy",p.id);const auto* m=original(messages,p.message_policy_id);if(!m||p.reply_node_id.empty()||p.reply_node_id.size()>256||p.collect_node_id.empty()||p.collect_node_id.size()>256||p.reply_node_id==p.collect_node_id)return common_failure("VisitReplyOriginalPolicyRequired",p.id);for(const auto& node:{p.reply_node_id,p.collect_node_id}){valid=declaration(interactions,*m,node);if(!valid.ok)return valid;}}return common_success();}
Outcome<VisitReplyCatalog> decode_visit_reply_catalog(const BoundaryValue& value,const VisitMessageCatalog& messages,const InteractionCatalog& interactions){try{using namespace boundary;std::set<StableId> keys;for(const auto& f:object(value,"visit_message_replies"))if(!keys.insert(f.first).second)fail("DuplicateVisitReplyField",f.first);fields(value,{"version","policies"},{},"visit_message_replies");VisitReplyCatalog result;result.version=get_int(value,"version","visit_message_replies");for(const auto& row:array(field(value,"policies","visit_message_replies"),"policies")){keys.clear();for(const auto& f:object(row,"policy"))if(!keys.insert(f.first).second)fail("DuplicateVisitReplyField",f.first);fields(row,{"id","message_policy_id","reply_node_id","collect_node_id"},{},"policy");result.policies.push_back({get_string(row,"id","policy"),get_string(row,"message_policy_id","policy"),get_string(row,"reply_node_id","policy"),get_string(row,"collect_node_id","policy")});}auto valid=validate_visit_reply_catalog(result,messages,interactions);return valid.ok?Outcome<VisitReplyCatalog>{true,std::move(result),{}}:Outcome<VisitReplyCatalog>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<VisitReplyState> make_initial_visit_reply_state(const VisitReplyCatalog&c,const VisitMessageCatalog&m,const InteractionCatalog&i){auto valid=validate_visit_reply_catalog(c,m,i);if(!valid.ok)return {false,{},valid.error};VisitReplyState state;state.version=c.version;return {true,std::move(state),{}};}
Status emit_visit_reply_catalog_fields(ProjectionWriter&w,const VisitReplyCatalog&c){w.field("version",c.version);w.sequence("policies",c.policies,[&](auto&out,const auto&p){return out.object("",[&](auto&row){row.field("id",p.id);row.field("message_policy_id",p.message_policy_id);row.field("reply_node_id",p.reply_node_id);row.field("collect_node_id",p.collect_node_id);return row.status();});});return w.status();}
BoundaryValue encode_visit_reply_catalog(const VisitReplyCatalog&c){BoundaryValue value;BoundaryProjectionWriter w(value);auto valid=w.object("",[&](auto&out){return emit_visit_reply_catalog_fields(out,c);});if(valid.ok)valid=w.finish();if(!valid.ok){boundary::DecodeFailure failure(valid.error.original.code,valid.error.original.path);failure.error=valid.error;throw failure;}return value;}
}
